import * as THREE from './vendor/three.module.js';
import {makeGhost,CHARACTERS,roundedBox} from './model.js';
const $=id=>document.getElementById(id);let selected=0,lineup=false,viewer;
$('ghostRoster').innerHTML=CHARACTERS.map((c,i)=>`<button class="ghost-choice" data-index="${i}" aria-pressed="${i===0}" style="--ghost-color:${c.color}"><i aria-hidden="true"></i><span><b>${c.name}</b><small>${c.title}</small></span></button>`).join('');
function select(i){selected=i;const c=CHARACTERS[i];$('ghostRole').textContent=c.title.toUpperCase();$('ghostName').innerHTML=`${c.name}<span>0${i+1} / 05</span>`;$('ghostBadge').textContent=`${c.sense.toUpperCase()} · ${c.ears==='cat'?'CAT GHOST':c.cyclops?'CYCLOPS GHOST':'BLOB GHOST'}`;$('ghostBadge').style.background=c.accent;$('ghostDescription').textContent=c.description;$('ghostTraits').innerHTML=c.traits.map(t=>`<li>${t}</li>`).join('');$('ghostDownload').href=`assets/ghosts/v002/${c.id}-v002.glb`;$('ghostDownload').innerHTML=`Download ${c.name}<span>↓</span>`;document.querySelectorAll('.ghost-choice').forEach((b,n)=>b.setAttribute('aria-pressed',n===i));viewer?.select(i,lineup);}
try{const el=$('ghostCanvas'),renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;el.appendChild(renderer.domElement);const scene=new THREE.Scene();scene.background=new THREE.Color('#deddd6');const camera=new THREE.PerspectiveCamera(30,1,.1,50);scene.add(new THREE.HemisphereLight('#ffffff','#b8b6a5',2));const key=new THREE.DirectionalLight('#fff2d5',3.3);key.position.set(-3,6,5);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-5,right:5,top:4,bottom:-4,near:.1,far:20});key.shadow.bias=-.0004;key.shadow.normalBias=.015;scene.add(key);const fill=new THREE.DirectionalLight('#d1def1',1);fill.position.set(3,2,-2);scene.add(fill);const floor=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:'#deddd6',roughness:1}));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;floor.position.y=-.05;scene.add(floor);const ghosts=CHARACTERS.map(c=>{const g=makeGhost(c.id,1.7);scene.add(g);return g;});let yaw=-.12,pointer=null;const calm=matchMedia('(prefers-reduced-motion: reduce)').matches;
function cameraUpdate(){const w=el.clientWidth,h=el.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/Math.max(h,1);camera.updateProjectionMatrix();const d=lineup?(camera.aspect<1.25?14/camera.aspect:10):6.7;camera.position.set(0,lineup?3.2:2.35,d);camera.lookAt(0,lineup?.62:.9,0);}new ResizeObserver(cameraUpdate).observe(el);cameraUpdate();viewer={select(i,all){ghosts.forEach((g,n)=>{g.visible=all||n===i;g.position.set(all?(n-2)*1.4:0,0,0);g.scale.set(1.7*CHARACTERS[n].width*(all?.78:1),1.7*CHARACTERS[n].height*(all?.78:1),1.7*(all?.78:1));});cameraUpdate();}};el.addEventListener('pointerdown',e=>{pointer=e.clientX;el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(pointer===null)return;yaw+=(e.clientX-pointer)*.009;pointer=e.clientX;});const end=()=>pointer=null;el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);const clock=new THREE.Clock();function frame(){requestAnimationFrame(frame);const t=clock.getElapsedTime(),stop=Math.floor(t*12)/12;ghosts.forEach((g,i)=>{g.rotation.y=yaw+(lineup?(i-2)*-.07:0);g.rotation.z=calm?0:Math.sin(stop*.75+i)*.012;g.position.y=calm?0:Math.max(0,Math.sin(stop*.9+i)*.018);});renderer.render(scene,camera);}frame();}catch(e){console.error('Ghost preview unavailable',e);$('studioError').hidden=false;}
$('ghostRoster').addEventListener('click',e=>{const b=e.target.closest('[data-index]');if(b)select(Number(b.dataset.index));});$('lineupBtn').addEventListener('click',()=>{lineup=!lineup;$('lineupBtn').textContent=lineup?'Focus on '+CHARACTERS[selected].name+' ↗':'Show the whole family ↗';viewer?.select(selected,lineup);});select(0);
